1: #!/usr/bin/env node
2: /**
3:  * tool-call-hygiene / morning-report.mjs —— 晨间失败巡检（给「今天要提防什么」一页结论）
4:  *
5:  * 三个脚本的分工：
6:  *   scan.mjs   只统计「工具层」失败率，纯文本。
7:  *   audit.mjs  工具层 + 供应商层，落盘 agent-failures-latest.json。
8:  *   morning-report.mjs  在此基础上做「晨报」：今天 vs 昨天对比，标出恶化项，
9:  *                       给出今天开局该守的 3 条重点，并落盘一份 markdown 到 ~/.dsh/reports/。
10:  *
11:  * 数据源：~/.dsh/sessions/<enc-cwd>/session-<id>/session.v4.jsonl.zstd（多帧 zstd，逐帧解）
12:  *   注意：tool/result 的调用 ID 在 data.message.toolCallId，不是 data.toolCallId。
13:  * 用法：node morning-report.mjs [YYYY-MM-DD]   # 缺省=今天；对比基准=前一天
14:  * 只依赖本地日志，不联网。
15:  */
16: import fs from 'fs';
17: import zlib from 'zlib';
18: import path from 'path';
19: import os from 'os';
20: 
21: const TZ = 8 * 3600 * 1000;
22: const arg = process.argv[2];
23: function dayStartOf(dstr) { return new Date(dstr + 'T00:00:00+08:00').getTime(); }
24: const todayLabel = arg || new Date(Date.now() + TZ).toISOString().slice(0, 10);
25: const todayStart = dayStartOf(todayLabel);
26: const yesterdayLabel = new Date(todayStart - 864e5 + TZ).toISOString().slice(0, 10);
27: 
28: const base = path.join(os.homedir(), '.dsh', 'sessions');
29: if (!fs.existsSync(base)) { console.error('未找到 sessions 目录: ' + base); process.exit(1); }
30: 
31: const ZSTD_MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
32: function zstdDecompressAll(buf) {
33:   const idxs = [];
34:   for (let i = 0; (i = buf.indexOf(ZSTD_MAGIC, i)) >= 0; i += 4) idxs.push(i);
35:   if (idxs.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString('utf8'); } catch { return buf.toString('utf8'); } }
36:   let out = '';
37:   for (let k = 0; k < idxs.length; k++) {
38:     const s = idxs[k], e = k + 1 < idxs.length ? idxs[k + 1] : buf.length;
39:     try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch {}
40:   }
41:   return out;
42: }
43: function load(fp) {
44:   const s = zstdDecompressAll(fs.readFileSync(fp));
45:   const ev = [];
46:   for (const l of s.split('\n')) { if (!l) continue; try { ev.push(JSON.parse(l)); } catch {} }
47:   return ev;
48: }
49: 
50: const SELF_HEAL = new Set([
51:   'INVALID_ARGS', 'ESCALATION_ARGS', 'FS_NOT_OBSERVED', 'FS_STALE_VERSION',
52:   'FS_NOT_FOUND', 'FS_NOT_TEXT', 'FS_EDIT_NOT_FOUND', 'GOAL_TOOL_INVALID_UPDATE',
53:   'GOAL_INVALID_TRANSITION', 'UNKNOWN_TOOL', 'SEARCH_FAILED', 'SEARCH_RAW_OUTPUT_OVERFLOW',
54:   'SEARCH_ABORTED', 'FS_NOT_DIRECTORY',
55: ]);
56: const MAXIS_MAP = { TIMEOUT: 'TOOL_TIMEOUT' };
57: 
58: function collectFiles(start, end) {
59:   const out = [];
60:   (function walk(p) {
61:     for (const e of fs.readdirSync(p, { withFileTypes: true })) {
62:       const fp = path.join(p, e.name);
63:       if (e.isDirectory()) walk(fp);
64:       else if (/\.jsonl\.zstd$/.test(e.name)) {
65:         const st = fs.statSync(fp);
66:         if (st.mtimeMs >= start && st.mtimeMs < end) out.push(fp);
67:       }
68:     }
69:   })(base);
70:   return out;
71: }
72: 
73: function summarize(files) {
74:   let calls = 0, toolFail = 0, provFail = 0;
75:   const byCategory = {};
76:   for (const fp of files) {
77:     const ev = load(fp);
78:     calls += ev.filter(e => e.type === 'tool/call').length;
79:     for (const tr of ev.filter(e => e.type === 'tool/result')) {
80:       const err = tr.data && tr.data.error; if (!err) continue;
81:       toolFail++;
82:       const code = MAXIS_MAP[String(err.code || err.name || 'OTHER')] || String(err.code || err.name || 'OTHER');
83:       byCategory[code] = (byCategory[code] || 0) + 1;
84:     }
85:     for (const e of ev) {
86:       if (!/llm\/(retry|error|failure)|provider/.test(e.type || '')) continue;
87:       const d = e.data || {};
88:       const fail = d.failure || {};
89:       const code = String(fail.code || d.code || '').toUpperCase();
90:       if (!code && !fail.message) continue;
91:       if (/EMPTY_RESPONSE/.test(code)) continue; // 空回复重试，不算供应商故障
92:       provFail++;
93:     }
94:   }
95:   const selfHeal = Object.entries(byCategory).filter(([k]) => SELF_HEAL.has(k)).reduce((a, [, v]) => a + v, 0);
96:   return { sessions: files.length, calls, toolFail, provFail, selfHeal, byCategory };
97: }
98: 
99: const today = summarize(collectFiles(todayStart, todayStart + 864e5));
100: const yest = summarize(collectFiles(todayStart - 864e5, todayStart));
101: 
102: const pct = (a, b) => b ? (a / b * 100).toFixed(1) : '-';
103: const delta = (a, b) => { const d = a - b; return (d > 0 ? '+' : '') + d; };
104: 
105: console.log('================ 工具失败 · 晨报 ================');
106: console.log('今天 ' + todayLabel + '  vs  昨天 ' + yesterdayLabel);
107: console.log('');
108: console.log('指标            今天        昨天        变化');
109: console.log('会话数          ' + String(today.sessions).padEnd(11) + String(yest.sessions).padEnd(11) + delta(today.sessions, yest.sessions));
110: console.log('工具调用        ' + String(today.calls).padEnd(11) + String(yest.calls).padEnd(11) + delta(today.calls, yest.calls));
111: console.log('工具失败        ' + String(today.toolFail).padEnd(11) + String(yest.toolFail).padEnd(11) + delta(today.toolFail, yest.toolFail));
112: console.log('  可自愈        ' + String(today.selfHeal).padEnd(11) + String(yest.selfHeal).padEnd(11) + delta(today.selfHeal, yest.selfHeal));
113: console.log('供应商失败      ' + String(today.provFail).padEnd(11) + String(yest.provFail).padEnd(11) + delta(today.provFail, yest.provFail));
114: console.log('失败率%         ' + pct(today.toolFail, today.calls).padEnd(11) + pct(yest.toolFail, yest.calls).padEnd(11));
115: 
116: console.log('\n-- 今天错误码 Top --');
117: Object.entries(today.byCategory).sort((a, b) => b[1] - a[1]).slice(0, 8).forEach(([k, v]) =>
118:   console.log('  ' + k.padEnd(26) + String(v).padStart(4) + (SELF_HEAL.has(k) ? '  [可自愈]' : '')));
119: 
120: const guards = [];
121: if (today.selfHeal > 0) {
122:   const top = Object.entries(today.byCategory).filter(([k]) => SELF_HEAL.has(k)).sort((a, b) => b[1] - a[1])[0];
123:   guards.push(`可自愈失败 ${today.selfHeal} 次（最多：${top ? top[0] : '-'}）→ 出错先查 tool-call-hygiene 修正表，绝不原样重复。`);
124: }
125: if (today.toolFail - today.selfHeal > 0) guards.push(`非自愈失败 ${today.toolFail - today.selfHeal} 次 → 多为超时/网络，拆小命令或加 timeoutMs。`);
126: if (today.provFail > 0) guards.push(`供应商失败 ${today.provFail} 次 → 连续 429/503 换 provider 同名模型，别原地重试。`);
127: if (!guards.length) guards.push('今日暂无显著失败，保持现有习惯。');
128: 
129: console.log('\n-- 今天开局该守 --');
130: guards.forEach((g, i) => console.log('  ' + (i + 1) + '. ' + g));
131: 
132: try {
133:   const reportDir = path.join(os.homedir(), '.dsh', 'reports');
134:   fs.mkdirSync(reportDir, { recursive: true });
135:   const md = [
136:     '# 工具失败晨报 · ' + todayLabel,
137:     '',
138:     '对比基准：' + yesterdayLabel,
139:     '',
140:     '| 指标 | 今天 | 昨天 | 变化 |',
141:     '|---|---|---|---|',
142:     `| 会话数 | ${today.sessions} | ${yest.sessions} | ${delta(today.sessions, yest.sessions)} |`,
143:     `| 工具调用 | ${today.calls} | ${yest.calls} | ${delta(today.calls, yest.calls)} |`,
144:     `| 工具失败 | ${today.toolFail} | ${yest.toolFail} | ${delta(today.toolFail, yest.toolFail)} |`,
145:     `| 　可自愈 | ${today.selfHeal} | ${yest.selfHeal} | ${delta(today.selfHeal, yest.selfHeal)} |`,
146:     `| 供应商失败 | ${today.provFail} | ${yest.provFail} | ${delta(today.provFail, yest.provFail)} |`,
147:     `| 失败率% | ${pct(today.toolFail, today.calls)} | ${pct(yest.toolFail, yest.calls)} | |`,
148:     '',
149:     '## 今天错误码 Top',
150:     ...Object.entries(today.byCategory).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([k, v]) => `- ${k}: ${v}${SELF_HEAL.has(k) ? '（可自愈）' : ''}`),
151:     '',
152:     '## 今天开局该守',
153:     ...guards.map((g, i) => `${i + 1}. ${g}`),
154:     '',
155:   ].join('\n');
